const DEBUG_QUERY_PARAM = 'debug';
const runtimeHost = globalThis as typeof globalThis & {
  __openLyricE2E?: unknown;
};

function isDebugQueryEnabled() {
  const searchParams = new URLSearchParams(globalThis.location?.search || '');

  return searchParams.get(DEBUG_QUERY_PARAM)?.trim().toLowerCase() === 'true';
}

function shouldLogKhmerTime() {
  return Boolean(runtimeHost.__openLyricE2E) || isDebugQueryEnabled();
}

export function logKhmerTime(logFunction, ...message) {
  if (!shouldLogKhmerTime()) {
    return;
  }

  if (!message.length) {
    return;
  }

  const [firstMessage, ...rest] = message;

  if (typeof firstMessage === 'string') {
    const prefixedMessage = firstMessage.startsWith('[Khmer timing]')
      ? firstMessage
      : `[Khmer timing] ${firstMessage}`;

    logFunction.call(console, prefixedMessage, ...rest);
    return;
  }

  logFunction.call(console, '[Khmer timing]', firstMessage, ...rest);
}
